export const meta = {
  name: 'server-mode-stub-verify',
  description: 'Verify 34 server-mode issue stubs against current beads main; adversarially check likely-fixed claims',
  phases: [
    { title: 'Verify', detail: '8 subtheme batch agents read code + upstream signals' },
    { title: 'Refute', detail: 'adversarial check on likely-fixed claims' },
  ],
}

const S = '/tmp/claude-1000/-var-home-matt-dev-mybd/524e528f-fb27-4deb-8156-929f23dbcefa/scratchpad'
const BATCHES = ['bootstrap','init-setup','proxied','server-lifecycle','write-loss','schema-locking','config-mode','perf-misc']
const startSpent = budget.spent()
const TARGET = budget.total ?? 200_000

const FINDINGS = {
  type: 'object', additionalProperties: false,
  required: ['stubs'],
  properties: { stubs: { type: 'array', items: {
    type: 'object', additionalProperties: false,
    required: ['bd_id','gh_issue','verdict','rationale','next_action'],
    properties: {
      bd_id: { type: 'string' },
      gh_issue: { type: 'integer' },
      verdict: { type: 'string', enum: ['still-valid','likely-fixed','needs-repro','misfiled'] },
      fix_evidence: { type: 'string', description: 'commit sha / PR number if likely-fixed, else empty' },
      rationale: { type: 'string', description: '2-4 sentences, cite file:line or commit' },
      next_action: { type: 'string', enum: ['keep','close','needs-repro-note','upstream-link-note'] },
      note: { type: 'string', description: 'one-line note to append to the bd stub' },
    } } } },
}

const VERDICT = {
  type: 'object', additionalProperties: false, required: ['refuted','reason'],
  properties: { refuted: { type: 'boolean' }, reason: { type: 'string' } },
}

const results = await pipeline(
  BATCHES,
  b => agent(`You are verifying mirrored upstream issue stubs for the beads project (repo gastownhall/beads, local source clone at /var/home/matt/dev/mybd/bd-main, freshly fetched ref upstream/main = c989b6b87). READ-ONLY task: do not edit files, do not run bd commands (the coordination DB must stay serial), do not post anything to GitHub.

Read the stub batch file ${S}/sm-batches/${b}.json — each entry has bd id, title, description, and external_ref gh-iss-NNNN (upstream issue number, all still OPEN as of today 2026-07-27).

For EACH stub decide, with evidence:
1. Is the described defect still present at upstream/main? Inspect the actual code in bd-main (use 'git -C /var/home/matt/dev/mybd/bd-main' with the upstream/main ref, e.g. git show upstream/main:path, git log upstream/main --oneline -- path, grep via git grep). The tree on disk may be behind upstream/main — always reference upstream/main, not the working tree.
2. Has recent work already fixed or partially addressed it? (git log upstream/main since ~2026-06-01 for the relevant files; also 'gh issue view NNNN --repo gastownhall/beads --comments' and cross-referenced PRs are allowed, read-only.)
3. Verdict per schema: still-valid | likely-fixed (must cite commit/PR in fix_evidence) | needs-repro (cannot determine from code reading; describe what a repro needs) | misfiled (description doesn't match reality).
Be conservative: 'likely-fixed' requires concrete evidence that the specific failure path changed, not just nearby activity. Return all stubs in the batch.`,
    { label: `verify:${b}`, phase: 'Verify', schema: FINDINGS }),
  (r, b) => {
    if (!r || !Array.isArray(r.stubs)) { log(`batch ${b}: null/malformed result, dropped`); return null }
    return r.stubs
  },
  async (stubs, b) => {
    if (!stubs) return null
    const fixed = stubs.filter(s => s.verdict === 'likely-fixed')
    const checked = await parallel(fixed.map(f => () =>
      agent(`Adversarially REFUTE this claim about the beads codebase (local clone /var/home/matt/dev/mybd/bd-main, ref upstream/main = c989b6b87; read-only, no bd commands): claim is that upstream issue gastownhall/beads#${f.gh_issue} ('${f.bd_id}') is already fixed by: ${f.fix_evidence}. Rationale given: ${f.rationale}
Inspect the cited commit/PR and the current code path at upstream/main. Default to refuted=true if the evidence does not clearly cover the specific failure mode in the issue. Refuted means: the issue is NOT convincingly fixed.`,
        { label: `refute:${f.bd_id}`, phase: 'Refute', schema: VERDICT })
        .then(v => ({ id: f.bd_id, refuted: v ? v.refuted : true, reason: v ? v.reason : 'verifier died' }))))
    const refutedMap = {}
    for (const c of checked.filter(Boolean)) refutedMap[c.id] = c
    return stubs.map(s => s.verdict === 'likely-fixed'
      ? { ...s, refute: refutedMap[s.bd_id] ?? { refuted: true, reason: 'no verifier result' } }
      : s)
  }
)

const flat = results.filter(Boolean).flat()
log(`verified ${flat.length}/34 stubs; spent ~${Math.round((budget.spent()-startSpent)/1000)}k of ${Math.round(TARGET/1000)}k target`)
if (flat.length < 34) log(`WARNING: ${34 - flat.length} stubs dropped (failed batches) — list them for a retry`)
return { count: flat.length, stubs: flat }
